#!/usr/bin/env python3
"""compare.py - build the cross-video comparison tables from pacing.json / audio.json files. Usage: compare.py OUT.md"""
import json, sys, os, numpy as np
R='/mnt/project-files/modern-vista-social/research/rick-style-spec/new-analysis/'
V=[('#21 drivers','21_e9NoHjAXYIY',R+'21_e9NoHjAXYIY/'),('#22 cart (9.2M)','22_i4hYq1oSXTg',R+'22_i4hYq1oSXTg/'),('#23 mine','23_TRUkQ1wbV2E',R+'23_TRUkQ1wbV2E/'),('#24 crash (10.1M)','24_aD73kaL_PtY',R+'24_aD73kaL_PtY/'),('#25 samurai','25_R-mWVMM-LAs',R+'25_R-mWVMM-LAs/'),
   ('#10 bell (orig)','10',R+'originals/10_GM9UKnZ6JFw/'),('#14 dragon (orig)','14',R+'originals/14_VS1Z_Q-Klt8/'),('BF round 3 (ours)','BF',R+'black-friday-round3/')]
P={};A={}
for lab,_,d in V:
    if os.path.exists(d+'pacing.json'): P[lab]=json.load(open(d+'pacing.json'))
    if os.path.exists(d+'audio.json'): A[lab]=json.load(open(d+'audio.json'))
labs=[l for l,_,_ in V if l in P]; new=[l for l in labs if l[1:3] in ('21','22','23','24','25')]; orig=[l for l in labs if 'orig' in l]; ours=[l for l in labs if 'ours' in l]
def g(d,path,default=None):
    for k in path.split('.'):
        if d is None: return default
        d=d.get(k) if isinstance(d,dict) else default
    return d
def rng(vals):
    v=[x for x in vals if isinstance(x,(int,float))]
    return (f"{min(v):.2f} to {max(v):.2f} (mean {np.mean(v):.2f})" if v else 'n/a')
def table(title, rows, src):
    o=[f"\n### {title}\n", '| metric | '+' | '.join(labs)+' | Rick new 5 range | Rick originals | ours (BF) | gap (BF vs new-5 mean) |', '|---|'+'---|'*(len(labs)+4)]
    for name,path in rows:
        vals={l:g(src.get(l),path) for l in labs}
        f=lambda x: ('n/a' if x is None else (f"{x:.2f}" if isinstance(x,float) else str(x)))
        nv=[vals[l] for l in new if isinstance(vals[l],(int,float))]; ov=[vals[l] for l in orig if isinstance(vals[l],(int,float))]; bv=[vals[l] for l in ours if isinstance(vals[l],(int,float))]
        gap = (f"{bv[0]-np.mean(nv):+.2f} ({(bv[0]/np.mean(nv)-1)*100:+.0f} %)" if nv and bv and np.mean(nv)!=0 else 'n/a')
        o.append(f"| {name} | "+' | '.join(f(vals[l]) for l in labs)+f" | {rng(nv)} | {rng(ov)} | {f(bv[0]) if bv else 'n/a'} | {gap} |")
    return '\n'.join(o)
out=["# Scene-time and audio comparison: Rick's 5 newest vs the 2 originals vs Black Friday round 3","Generated by new-analysis/_tools/compare.py from each video's pacing.json and audio.json (tools: pacing.py, audio.py; joins = visually verified lists, BF = true shot ranges from the build). All videos measured with identical code and thresholds.\n"]
out.append(table('1. Shot length (from verified joins)',[('duration s','duration_s'),('joins','joins.n'),('joins per 10 s','joins.per_10s'),('hard/fast joins (<=3 f)','joins.fast_or_hard'),('dissolves','joins.dissolves'),('dissolve median length f','joins.dissolve_len_median_f'),('shots','shots_all.n'),('ASL s','shots_all.asl'),('median s','shots_all.median'),('mode (0.5 s bin)','shots_all.mode_0p5s_bin'),('min s','shots_all.min'),('max s','shots_all.max'),('P10 s','shots_all.p10'),('P90 s','shots_all.p90'),('shots per min','shots_all.shots_per_min'),('share < 1 s','shots_all.share_lt1'),('share < 2 s','shots_all.share_lt2'),('share > 4 s','shots_all.share_gt4')],P))
secrows=[]
for s in ['hook_0-3s','3-15s','body','payoff','outro']:
    secrows += [(f'{s}: joins',f'sections.{s}.joins'),(f'{s}: cuts per min',f'sections.{s}.cuts_per_min'),(f'{s}: mean visible shot time s',f'sections.{s}.mean_visible_shot_time'),(f'{s}: ASL of shots starting here s',f'sections.{s}.shots_starting_here.asl')]
out.append(table('2. Per section',secrows,P))
out.append(table('3. Captions (text pops) on-screen dwell',[('caption swaps per s','captions.swaps_per_s'),('dwell mean s','captions.dwell_s.mean'),('dwell median s','captions.dwell_s.median'),('dwell P10 s','captions.dwell_s.p10'),('dwell P90 s','captions.dwell_s.p90'),('dwell max s','captions.dwell_s.max'),('caption on-screen share','captions.caption_on_share')],P))
out.append(table('4. Cut rate vs visual-change rate',[('joins','visual_change.joins'),('camera events (move starts + speed bursts)','visual_change.camera_events'),('object/character motion events','visual_change.object_events'),('caption swaps','visual_change.caption_swaps'),('changes per min, no captions','visual_change.changes_per_min_no_captions'),('changes per min, all','visual_change.changes_per_min_all'),('mean gap between changes s (no captions)','visual_change.mean_gap_between_changes_s_no_captions'),('camera moving share','visual_change.camera_moving_share'),('camera speed median','visual_change.camera_speed_median'),('camera speed P90','visual_change.camera_speed_p90'),('object motion median','visual_change.object_motion_median'),('still frame share','visual_change.still_frame_share'),('longest still run f','visual_change.longest_still_run_f')],P))
out.append(table('5. Cut-to-narration alignment',[('words','narration.words'),('words per s','narration.words_per_s'),('sentences','narration.sentences'),('phrases (punctuation; auto-caption punctuation is sparse, so [uncertain])','narration.phrases'),('cuts per sentence','narration.cuts_per_sentence'),('cuts per phrase','narration.cuts_per_phrase'),('sentences with 0 cuts','narration.sentences_with_0_cuts'),('max cuts in one sentence','narration.max_cuts_in_one_sentence'),('seconds per sentence','narration.seconds_per_sentence'),('join start within 2 f of a word onset','narration.join_start_within_2f_of_word_onset'),('(chance level for that)','narration.chance_within_2f_of_word_onset'),('join start within 3 f of a phrase onset','narration.join_start_within_3f_of_phrase_onset'),('join start within 6 f of a sentence onset','narration.join_start_within_6f_of_sentence_onset'),('video end after last word start s','narration.end_after_last_word_start_s')],P))
# pacing curve
o=["\n### 6. Pacing curve (10 equal time deciles): joins / visual changes per s without captions\n",'| decile | '+' | '.join(labs)+' |','|---|'+'---|'*len(labs)]
for i in range(10):
    o.append(f"| {i*10}-{i*10+10} % | "+' | '.join(f"{P[l]['pacing_curve_deciles'][i]['joins']} / {P[l]['pacing_curve_deciles'][i]['changes_per_s_no_captions']}" for l in labs)+' |')
out.append('\n'.join(o))
labs=[l for l,_,_ in V if l in A]; new=[l for l in labs if l[1:3] in ('21','22','23','24','25')]; orig=[l for l in labs if 'orig' in l]; ours=[l for l in labs if 'ours' in l]
out.append(table('7. Loudness and mix (stems separated by rea-video for every video, same method)',[('mix integrated LUFS','loudness.mix.I_LUFS'),('mix LRA LU','loudness.mix.LRA_LU'),('mix true peak dBTP','loudness.mix.true_peak_dBTP'),('VO stem LUFS','loudness.vo_stem_I_LUFS'),('music+SFX stem LUFS','loudness.music_stem_I_LUFS'),('music-to-VO gap mean dB','music_to_vo_gap_dB.mean'),('gap median dB','music_to_vo_gap_dB.median'),('gap min dB (music closest to voice)','music_to_vo_gap_dB.min'),('gap max dB','music_to_vo_gap_dB.max'),('gap std dB','music_to_vo_gap_dB.std'),('music level std dB (3 s windows)','music_level_stability.std_dB'),('music level range dB','music_level_stability.range_dB'),('max level step per 0.5 s dB','music_level_stability.max_step_per_0p5s_dB'),('duck depth dB (gaps minus under-VO)','ducking.duck_depth_dB'),('VO/music envelope correlation','ducking.envelope_correlation_vo_vs_music')],A))
out.append(table('8. Music content',[('BPM (beat tracker)','tempo.bpm_beat_track'),('inter-beat std ms','tempo.inter_beat_std_ms'),('onsets per s','onsets.per_s'),('strong onsets per 10 s','onsets.strong_per_10s'),('off-grid strong onsets per 10 s (SFX candidates) [heuristic]','sfx_candidates.per_10s'),('energy share sub < 60 Hz','timbre.energy_share.sub_lt60'),('bass 60-250 Hz','timbre.energy_share.bass_60_250'),('low-mid 250 Hz-1 k','timbre.energy_share.lowmid_250_1k'),('mid 1-4 k','timbre.energy_share.mid_1k_4k'),('high > 4 k','timbre.energy_share.high_gt4k'),('spectral centroid Hz','timbre.spectral_centroid_hz'),('percussive/harmonic energy','timbre.percussive_to_harmonic_energy'),('first music onset s','first_3s.first_music_onset_s'),('first strong onset s','first_3s.first_strong_onset_s'),('music median dB','first_3s.music_median_dB_whole'),('VO first sound s','first_3s.vo_first_sound_s')],A))
o=["\n### 9. Key (Krumhansl profile on harmonic stem) and structure\n",'| video | key | score | 2nd | confidence | bpm per 10 s | loop [heuristic] | sections (start s: mean dB) |','|---|---|---|---|---|---|---|---|']
for l in labs:
    a=A[l]; ss=a.get('structure_sections'); o.append(f"| {l} | {a['key']['best']} | {a['key']['score']} | {a['key']['second']} | {a['key']['confidence']} | {' '.join(str(x[1]) for x in a['tempo']['bpm_per_10s'])} | {g(a,'loop.most_likely_loop_beats')} beats = {g(a,'loop.loop_seconds')} s | {'; '.join(f"{s['start_s']}: {s['mean_dB']}" for s in ss) if isinstance(ss,list) else ss} |")
out.append('\n'.join(o))
syn=[(k,k) for k in ['join_start_to_beat','join_mid_to_beat','join_start_to_strong_onset','join_mid_to_strong_onset','camera_event_to_beat','camera_event_to_strong_onset','object_event_to_strong_onset','caption_swap_to_beat','caption_swap_to_strong_onset']]
o=["\n### 10. Sync of picture events to music (share within +/-2 f; lift = share / chance; lift near 1 = no sync)\n",'| event to target | '+' | '.join(labs)+' |','|---|'+'---|'*len(labs)]
for k,_ in syn: o.append(f"| {k} | "+' | '.join((f"{A[l]['sync'][k]['within_2f']:.2f} (x{A[l]['sync'][k]['lift']})" if A[l]['sync'].get(k) else 'n/a') for l in labs)+' |')
out.append('\n'.join(o))
o=["\n### 11. Music level over time (LUFS, 3 s windows, every 5 s) and music-to-VO gap\n",'| t s | '+' | '.join(labs)+' |','|---|'+'---|'*len(labs)]
for t in range(2,66,4):
    row=[]
    for l in labs:
        c=dict((round(x[0],1),x[1]) for x in A[l]['music_level_curve_LUFS_3s']); k=min(c,key=lambda q:abs(q-t)) if c else None
        row.append(str(c[k]) if k is not None and abs(k-t)<=1 else '')
    o.append(f"| {t} | "+' | '.join(row)+' |')
out.append('\n'.join(o))
open(sys.argv[1],'w').write('\n'.join(out)+'\n'); print('wrote',sys.argv[1],'videos',labs)
